goodExample.code:
// Good: Testing accessible user behavior
test('expands content when user clicks header', async () => {
  render(<Accordion title="FAQ" content="Answer" />);
  const button = screen.getByRole('button', { name: /FAQ/i });
  expect(screen.queryByText(/Answer/i)).not.toBeVisible();

  await userEvent.click(button);
  expect(screen.getByText(/Answer/i)).toBeVisible();
});
